{
  "claims": [
    {
      "anchor": "SQLite's default maximum string or BLOB length is one billion bytes",
      "claim_text": "The default maximum string or BLOB length in SQLite is one billion bytes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S1 states the default value of SQLITE_MAX_LENGTH is 1 billion."
    },
    {
      "anchor": "the implementation cannot go beyond 2147483645 bytes",
      "claim_text": "The current implementation supports string or BLOB length only up to 2147483645 bytes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S0 states the implementation supports length up to 2147483645."
    },
    {
      "anchor": "functions such as hex() may fail well before that",
      "claim_text": "Built-in functions such as hex() may fail well before the maximum length.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S1 states hex() might fail well before that point."
    },
    {
      "anchor": "each row is encoded as a single BLOB during INSERT and SELECT",
      "claim_text": "During part of INSERT and SELECT processing, each row is encoded as a single BLOB.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S0 states the complete content of each row is encoded as a single BLOB."
    },
    {
      "anchor": "SQLITE_MAX_LENGTH also caps the size of a row",
      "claim_text": "SQLITE_MAX_LENGTH also determines the maximum number of bytes in a row.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S1 states SQLITE_MAX_LENGTH also determines the maximum bytes in a row."
    },
    {
      "anchor": "Large values should be bound with sqlite3_bind_XXXX() instead of embedded as literals",
      "claim_text": "Large values should be bound with sqlite3_bind_XXXX() rather than embedded as literals.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S2", "rel": "entails"},
        {"sid": "P4.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P3.S2 says use host parameters; P4.S0 says use sqlite3_bind_XXXX() to bind large string values."
    },
    {
      "anchor": "binding reduces the risk of SQL injection",
      "claim_text": "Binding reduces the risk of SQL injection attacks.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P4.S1 states binding reduces the risk of SQL injection attacks."
    },
    {
      "anchor": "binding runs faster",
      "claim_text": "Binding runs faster.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P4.S2 states it also runs faster."
    },
    {
      "anchor": "Values that do not fit in one page are stored in overflow pages",
      "claim_text": "Values that do not fit in one page are stored in overflow pages.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions overflow pages."
    },
    {
      "anchor": "BLOBs can also be read incrementally with sqlite3_blob_open()",
      "claim_text": "BLOBs can be read incrementally with sqlite3_blob_open().",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions sqlite3_blob_open() or incremental reading."
    },
    {
      "anchor": "The default column limit is 2000",
      "claim_text": "The default setting for SQLITE_MAX_COLUMN is 2000.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P5.S0 states the default setting for SQLITE_MAX_COLUMN is 2000."
    },
    {
      "anchor": "some code-generator algorithms are O(N²) in the number of columns",
      "claim_text": "Some code-generator algorithms are O(N²) where N is the number of columns.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P6.S1 states there are algorithms that are O(N²) where N is the number of columns."
    },
    {
      "anchor": "a huge SQLITE_MAX_COLUMN can make sqlite3_prepare_v2() slow",
      "claim_text": "If SQLITE_MAX_COLUMN is redefined to a really huge number and SQL uses a large number of columns, sqlite3_prepare_v2() may run slowly.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P6.S2 states this conditional consequence."
    },
    {
      "anchor": "PostgreSQL allows up to 1600 columns per table",
      "claim_text": "PostgreSQL allows up to 1600 columns per table.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions PostgreSQL."
    }
  ]
}
